(function(){
 const activeStatuses=['accepted','collected','courier_completed'],PENDING_KEY='zwconnect-pending-courier-location-v1';
 let locationWatch=null,lastSentAt=0,lastDeliveryId=null,sharingState='Waiting for an active job';
 function activeJob(){return jobs.find(j=>activeStatuses.includes(j.status))}
 function trackingNotice(active){return active?`<div class="courier-tracking-notice"><span><i data-lucide="navigation"></i></span><div><strong>Live customer tracking is on</strong><small>${sharingState}. Location is shared only with this order's private tracking code.</small></div></div>`:''}
 jobList=function(){const active=activeJob();return `<div class="job-list">${trackingNotice(active)}${active?`<div class="rate-preview"><strong>One active job enforced</strong><small>Complete the current delivery and wait for customer receipt before accepting another.</small></div>`:''}${jobs.map(j=>`<div class="job courier-job"><span><i data-lucide="${j.status==='open'?'bike':j.status==='courier_completed'?'hourglass':'package-check'}"></i></span><div><strong>${j.shop} → ${j.destination}</strong><small>${j.parcel}</small><small>${Number(j.toPickup).toFixed(1)} km courier-to-shop • about ${Math.max(1,Math.ceil(Number(j.toPickup)/15*60))} min to collection • ${Number(j.distance).toFixed(1)} km shop-to-customer • ${j.status.replace('_',' ')}</small><nav><a href="${mapsUrl(j.pickupLat,j.pickupLng)}" target="_blank" rel="noopener"><i data-lucide="navigation"></i> Directions to shop</a><a href="${mapsUrl(j.dropLat,j.dropLng)}" target="_blank" rel="noopener"><i data-lucide="map-pinned"></i> Directions to customer</a></nav></div><div><small>${j.status==='open'?'Minimum fare':'Delivery fare'}</small><b>US$ ${Number(j.status==='open'?j.minFare:j.fee).toFixed(2)}</b>${j.status==='open'&&!active?`<button data-accept-job="${j.id}">Submit fare</button>`:''}${j.status==='open'&&active?'<span class="status">Locked</span>':''}${j.status==='accepted'?`<button data-delivery-step="${j.id}" data-next-status="collected">Mark collected</button>`:''}${j.status==='collected'?`<button data-delivery-step="${j.id}" data-next-status="courier_completed">Mark delivery completed</button>`:''}${j.status==='courier_completed'?'<span class="status">Waiting for customer receipt</span>':''}</div></div>`).join('')}</div>`}
 function pendingLocation(){try{return JSON.parse(localStorage.getItem(PENDING_KEY)||'null')}catch{return null}}
 function savePending(payload){localStorage.setItem(PENDING_KEY,JSON.stringify(payload))}
 async function sendLocation(payload){if(!window.zwconnectSupabase||!navigator.onLine){savePending(payload);sharingState='Location saved offline';return}const {error}=await window.zwconnectSupabase.rpc('update_courier_location',{target_delivery:payload.deliveryId,courier_lat:payload.latitude,courier_lng:payload.longitude,location_accuracy:payload.accuracy,courier_speed_kph:payload.speedKph,courier_heading:payload.heading});if(error){savePending(payload);sharingState='Location queued for retry';throw error}localStorage.removeItem(PENDING_KEY);lastSentAt=Date.now();sharingState=`Updated ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`}
 function positionPayload(job,position){const speed=Number.isFinite(position.coords.speed)?Math.min(120,Math.max(0,position.coords.speed*3.6)):null;return{deliveryId:job.id,latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy:Number.isFinite(position.coords.accuracy)?position.coords.accuracy:null,speedKph:speed,heading:Number.isFinite(position.coords.heading)?position.coords.heading:null,recordedAt:new Date().toISOString()}}
 function ensureLocationWatch(){const active=activeJob();if(!active){if(locationWatch!==null)navigator.geolocation.clearWatch(locationWatch);locationWatch=null;lastDeliveryId=null;return}if(!navigator.geolocation){sharingState='Location is unavailable on this device';return}if(locationWatch!==null&&lastDeliveryId===active.id)return;if(locationWatch!==null)navigator.geolocation.clearWatch(locationWatch);lastDeliveryId=active.id;sharingState='Requesting location permission';locationWatch=navigator.geolocation.watchPosition(position=>{const current=activeJob();if(!current)return;const payload=positionPayload(current,position);savePending(payload);if(Date.now()-lastSentAt>=10000)sendLocation(payload).catch(()=>{});render()},()=>{sharingState='Enable precise location to let the customer track you';render()},{enableHighAccuracy:true,maximumAge:5000,timeout:15000})}
 async function flushPendingLocation(){const pending=pendingLocation(),active=activeJob();if(pending&&active&&pending.deliveryId===active.id)try{await sendLocation(pending);render()}catch{}}
 document.addEventListener('DOMContentLoaded',()=>{setInterval(hydrateJobs,30000);setInterval(ensureLocationWatch,3000);setTimeout(ensureLocationWatch,1500)});
 window.addEventListener('online',flushPendingLocation);
 document.addEventListener('click',async e=>{const step=e.target.closest('[data-delivery-step]');if(!step)return;const job=jobs.find(j=>j.id===step.dataset.deliveryStep),status=step.dataset.nextStatus,question=status==='collected'?'Confirm that you collected this parcel?':'Confirm delivery to the customer? The customer must still mark it received.';if(!job||!confirm(question))return;job.status=status;await window.ZWOffline.enqueue('delivery.status',{deliveryId:job.id,status},{role:'courier'});toast(status==='collected'?'Parcel marked collected':'Delivery marked complete — awaiting customer receipt');render();ensureLocationWatch()});
})();
